#!/usr/bin/env node
// Inspect the most recent pi session JSONL for a given project and report
// real boot-context numbers: cacheRead (stable cached prefix), cacheWrite
// (this-session-new), per-turn delta, and total input footprint.
//
// Usage:
//   node scripts/check-session-context.mjs           # auto-detect from $PWD
//   node scripts/check-session-context.mjs <path>    # specific cwd
//   node scripts/check-session-context.mjs --session <jsonl>
//   node scripts/check-session-context.mjs --json

import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";

const args = process.argv.slice(2);
const json = args.includes("--json");
const sessionFlagIdx = args.indexOf("--session");
const explicitSession = sessionFlagIdx >= 0 ? args[sessionFlagIdx + 1] : null;
const cwd = resolve(
  args.find((a, i) => !a.startsWith("--") && args[i - 1] !== "--session") ?? process.cwd(),
);

function findLatestSession(targetCwd) {
  // pi session dirs encode the cwd as -- separated path
  const sessionsRoot = join(homedir(), ".pi", "agent", "sessions");
  if (!existsSync(sessionsRoot)) return null;
  const slug = targetCwd.replace(/\//g, "-");
  const candidates = readdirSync(sessionsRoot).filter((d) => d.includes(slug));
  if (candidates.length === 0) return null;

  let best = null;
  for (const dir of candidates) {
    const fullDir = join(sessionsRoot, dir);
    for (const file of readdirSync(fullDir)) {
      if (!file.endsWith(".jsonl")) continue;
      const p = join(fullDir, file);
      const mtime = statSync(p).mtimeMs;
      if (!best || mtime > best.mtime) best = { path: p, mtime };
    }
  }
  return best?.path ?? null;
}

const sessionPath = explicitSession ?? findLatestSession(cwd);
if (!sessionPath) {
  console.error(`No pi session found for ${cwd}`);
  process.exit(1);
}

const lines = readFileSync(sessionPath, "utf8").split("\n").filter(Boolean);
const turns = [];
let model = null;
for (const line of lines) {
  let d;
  try { d = JSON.parse(line); } catch { continue; }
  if (d.type === "model_change") model = d.modelId;
  if (d.type !== "message") continue;
  const m = d.message;
  if (m?.role !== "assistant" || !m.usage) continue;
  turns.push({
    timestamp: d.timestamp,
    model: m.model ?? model,
    input: m.usage.input ?? 0,
    output: m.usage.output ?? 0,
    cacheRead: m.usage.cacheRead ?? 0,
    cacheWrite: m.usage.cacheWrite ?? 0,
    total: m.usage.totalTokens ?? 0,
  });
}

if (turns.length === 0) {
  console.error(`No assistant turns with usage in ${sessionPath}`);
  process.exit(1);
}

const boot = turns[0];
const last = turns[turns.length - 1];
const result = {
  session: sessionPath,
  cwd,
  turns: turns.length,
  model: boot.model,
  boot: {
    input: boot.input,
    cacheRead: boot.cacheRead,
    cacheWrite: boot.cacheWrite,
    output: boot.output,
    total_input_footprint: boot.input + boot.cacheRead + boot.cacheWrite,
  },
  cumulative: {
    input: turns.reduce((s, t) => s + t.input, 0),
    output: turns.reduce((s, t) => s + t.output, 0),
    cacheRead: turns.reduce((s, t) => s + t.cacheRead, 0),
    cacheWrite: turns.reduce((s, t) => s + t.cacheWrite, 0),
  },
  last_turn: last,
};

if (json) {
  console.log(JSON.stringify(result, null, 2));
} else {
  const fmt = (n) => n.toLocaleString();
  const home = homedir();
  const short = (p) => (p.startsWith(home) ? "~" + p.slice(home.length) : p);
  console.log(`Session: ${short(result.session)}`);
  console.log(`CWD:     ${short(cwd)}`);
  console.log(`Model:   ${result.model}`);
  console.log(`Turns:   ${result.turns}\n`);
  console.log("Boot turn (first assistant response):");
  console.log(`  cacheRead   ${fmt(result.boot.cacheRead).padStart(10)}  (already-cached prefix from prior sessions)`);
  console.log(`  cacheWrite  ${fmt(result.boot.cacheWrite).padStart(10)}  (new cached prefix this session)`);
  console.log(`  input       ${fmt(result.boot.input).padStart(10)}  (uncached prompt bytes)`);
  console.log(`  output      ${fmt(result.boot.output).padStart(10)}`);
  console.log(`  ─────────────────────`);
  console.log(`  boot footprint: ${fmt(result.boot.total_input_footprint)} input tokens\n`);
  console.log("Cumulative across session:");
  console.log(`  cacheRead   ${fmt(result.cumulative.cacheRead).padStart(10)}`);
  console.log(`  cacheWrite  ${fmt(result.cumulative.cacheWrite).padStart(10)}`);
  console.log(`  input       ${fmt(result.cumulative.input).padStart(10)}`);
  console.log(`  output      ${fmt(result.cumulative.output).padStart(10)}`);

  const cacheHitRate =
    result.cumulative.cacheRead /
      (result.cumulative.cacheRead + result.cumulative.cacheWrite + result.cumulative.input || 1);
  console.log(`\n  cache hit rate: ${(cacheHitRate * 100).toFixed(1)}%`);
}

